begin;
create temp table agent_fixture(u uuid,v uuid,run uuid,lease uuid);
insert into agent_fixture values(gen_random_uuid(),gen_random_uuid(),null,null);
insert into auth.users(id,email) select u,'agent-fixture-'||u::text||'@example.invalid' from agent_fixture union all select v,'agent-fixture-'||v::text||'@example.invalid' from agent_fixture;
grant select,update on agent_fixture to authenticated;
create temp table ledger_before as select count(*) n,sum(amount) total from transactions;
do $$declare f record;j jsonb;k jsonb;spent jsonb;blocked boolean;begin
 select * into f from agent_fixture;
 insert into finance_ai_connections(owner_id,provider,model,credential,key_suffix,request_limit) values(f.u,'anthropic','claude-sonnet-5-5',repeat('x',80),'test',20);
 insert into finance_ai_settings(owner_id,active_provider) values(f.u,'anthropic');
 insert into finance_ai_budgets(owner_id,daily_micros,monthly_micros) values(f.u,1000000,5000000);
 j:=finance_ai_reserve(f.u,gen_random_uuid(),repeat('a',64),repeat('b',64),1000,6000,false,'anthropic','claude-sonnet-5-5');
 if j->>'status'<>'new' then raise exception 'Missing reservation';end if;
 update agent_fixture set run=(j->>'id')::uuid;
 spent:=finance_ai_spending(f.u);if (spent->>'held')::bigint<>70192 then raise exception 'Unexpected maximum cost %',spent;end if;
 blocked:=false;begin perform finance_ai_reserve(f.u,gen_random_uuid(),repeat('c',64),repeat('d',64),1000,6000,false,'anthropic','claude-sonnet-5-5');exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Concurrent inference allowed';end if;
 perform finance_ai_mark_sent(f.u,(j->>'id')::uuid);
 blocked:=false;begin perform finance_ai_mark_sent(f.u,(j->>'id')::uuid);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Duplicate provider send allowed';end if;
 perform finance_ai_settle(f.u,(j->>'id')::uuid,'{"input":100,"cached":20,"cacheWrite":0,"output":50,"searches":0}','synthetic');
 perform finance_ai_settle(f.u,(j->>'id')::uuid,'{"input":999,"cached":0,"cacheWrite":0,"output":999,"searches":0}','synthetic');
 if (select cost_micros from finance_ai_charges where run_id=(j->>'id')::uuid)<>702 then raise exception 'Usage settlement is wrong or not idempotent';end if;
 update finance_ai_receipt_runs set status='succeeded',result='{"summary":"synthetic cached result"}' where id=(j->>'id')::uuid;
 k:=finance_ai_reserve(f.u,gen_random_uuid(),repeat('c',64),repeat('b',64),1000,6000,false,'anthropic','claude-sonnet-5-5');if k->>'status'<>'succeeded' then raise exception 'Same evidence was charged twice';end if;
 update finance_ai_budgets set daily_micros=71000 where owner_id=f.u;
 blocked:=false;begin perform finance_ai_reserve(f.u,gen_random_uuid(),repeat('e',64),repeat('f',64),2000,6000,false,'anthropic','claude-sonnet-5-5');exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Daily cost limit bypass';end if;
 update finance_ai_budgets set daily_micros=1000000,monthly_micros=1000000 where owner_id=f.u;
 blocked:=false;begin perform finance_ai_reserve(f.u,gen_random_uuid(),repeat('e',64),repeat('f',64),2000,6000,true,'anthropic','claude-sonnet-5-5');exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Research maximum escaped budget';end if;
 j:=finance_ai_reserve(f.u,gen_random_uuid(),repeat('e',64),repeat('f',64),1000,6000,false,'anthropic','claude-sonnet-5-5');perform finance_ai_mark_sent(f.u,(j->>'id')::uuid);perform finance_ai_settle(f.u,(j->>'id')::uuid,null);
 if (select state from finance_ai_charges where run_id=(j->>'id')::uuid)<>'uncertain' then raise exception 'Timeout released possible charge';end if;
 update finance_ai_receipt_runs set status='failed' where id=(j->>'id')::uuid;
 update finance_ai_charges set started_at=now()-interval '40 days' where run_id=(j->>'id')::uuid;
 spent:=finance_ai_spending(f.u);if (spent->>'held')::bigint<>70192 then raise exception 'Uncertain charge fell out of budget at rollover';end if;
 j:=finance_ai_reserve(f.u,gen_random_uuid(),repeat('1',64),repeat('2',64),1000,6000,false,'anthropic','claude-sonnet-5-5');
 update finance_ai_charges set started_at=now()-interval '11 minutes' where run_id=(j->>'id')::uuid;
 update finance_ai_receipt_runs set started_at=now()-interval '11 minutes' where id=(j->>'id')::uuid;
 perform finance_ai_reap();if (select state from finance_ai_charges where run_id=(j->>'id')::uuid)<>'released' then raise exception 'Unsent reservation not released';end if;
 blocked:=false;begin perform finance_ai_mark_sent(f.u,(j->>'id')::uuid);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Reaped attempt was sent';end if;
 insert into finance_autopilot_settings(owner_id,enabled,background_enabled,provider,model) values(f.u,true,true,'anthropic','claude-sonnet-5-5');
 j:=finance_autopilot_begin(f.u);update agent_fixture set lease=(j->>'lease')::uuid;k:=finance_autopilot_begin(f.u);if k->>'busy'<>'true' then raise exception 'Second worker acquired live lease';end if;
 blocked:=false;begin perform finance_worker_command(f.u,(j->>'lease')::uuid,'finance_set_ai_budget','{}');exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Worker changed spending consent';end if;
 if finance_worker_valid(f.v,(j->>'lease')::uuid) then raise exception 'Worker crossed owner boundary';end if;
 perform finance_autopilot_end(f.u,gen_random_uuid(),'idle','wrong lease','[]');if not finance_worker_valid(f.u,(j->>'lease')::uuid) then raise exception 'Wrong worker released lease';end if;
 update finance_autopilot_settings set enabled=false where owner_id=f.u;if finance_worker_valid(f.u,(j->>'lease')::uuid) then raise exception 'Pause failed to revoke lease';end if;
end;$$;
set local role authenticated;
do $$declare f record;blocked boolean;s jsonb;begin
 select * into f from agent_fixture;perform set_config('request.jwt.claim.sub',f.u::text,true);
 s:=finance_ai_cost_status();if (s->'usage'->>'held')::bigint<>70192 then raise exception 'Owner cost summary missing';end if;
 perform finance_set_ai_budget(0,0,1);
 blocked:=false;begin perform finance_set_ai_budget(1000000,5000000,1);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Stale budget overwrote pause';end if;
 blocked:=false;begin perform finance_ai_reserve(f.u,gen_random_uuid(),repeat('a',64),repeat('b',64),1000,6000,false,'anthropic','claude-sonnet-5-5');exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Browser could allocate another owner budget';end if;
 blocked:=false;begin perform finance_worker_command(f.u,f.lease,'finance_ai_status','{}');exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Browser reached internal worker command';end if;
 blocked:=false;begin perform * from finance_ai_charges;exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Browser read raw cost records';end if;
 perform set_config('request.jwt.claim.sub',f.v::text,true);if exists(select 1 from finance_ai_budgets where owner_id=f.u) then raise exception 'Partner read private budget';end if;
 if (finance_ai_cost_status()->'usage'->>'held')::bigint<>0 then raise exception 'Partner saw cost activity';end if;
end;$$;
reset role;
do $$begin if exists(select 1 from ledger_before where n<>(select count(*) from transactions) or total is distinct from (select sum(amount) from transactions)) then raise exception 'Cost controls changed financial history';end if;end;$$;
rollback;
